/**
 * Nodra methods for the "OfferLots" doctype.
 *
 * Generated by `new:method OfferLots`.
 *
 * Register this module from the app's method bootstrap.
 */
import type { MethodRegistry } from "nodra";
import { getNodra } from "../nodra-app";
import { serialise } from "../http";
import { StockService } from "../services/stock.service";

type RecordData = Record<string, unknown>;

function isRecord(value: unknown): value is RecordData {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function toNumber(value: unknown): number {
  const number = Number(value ?? 0);
  return Number.isFinite(number) ? number : 0;
}

function toDateValue(value: unknown): number {
  if (!value) return 0;

  const timestamp = new Date(String(value)).getTime();

  return Number.isFinite(timestamp) ? timestamp : 0;
}

export function registerOfferLotsMethods(registry: MethodRegistry): void {
  registry.register(
    "offers.report.index",
    async (ctx) => {
      const app = await getNodra();

      const args = (ctx.args ?? {}) as {
        limit?: number;
        offset?: number;
        sort_order?: "asc" | "desc";
      };

      const limit = Math.min(Math.max(Number(args.limit) || 100, 1), 1000);
      const offset = Math.max(Number(args.offset) || 0, 0);
      const sortOrder = args.sort_order === "asc" ? "asc" : "desc";

      const [
        lotDocuments,
        offerDocuments,
        saleBookDocuments,
        teaTestingDocuments,
        totalCount,
      ] = await Promise.all([
        app.orm.getList("Lots", {
          limit,
          offset,
          orderBy: `entry_date ${sortOrder}`,
        }),
        app.orm.getList("OfferSheet", {
          limit: 1000,
          offset: 0,
          orderBy: "offer_date desc",
        }),
        app.orm.getList("SaleBook", {
          limit: 1000,
          offset: 0,
          orderBy: "modified desc",
        }),
        app.orm.getList("TeaTesting", {
          limit: 1000,
          offset: 0,
          orderBy: "sample_date desc",
        }),
        app.orm.getCount("Lots"),
      ]);

      // OfferSheet rows grouped by Lot.
      const offersByLot = new Map<string, Array<Record<string, unknown>>>();

      for (const document of offerDocuments) {
        const offer = serialise(document);

        const offerLots = Array.isArray(offer.offer_lots)
          ? offer.offer_lots
          : [];

        for (const item of offerLots) {
          const offerLot = item as Record<string, unknown>;

          // Use Link field, not the display field lot_no.
          const lotName = String(offerLot.lot ?? "").trim();

          if (!lotName) continue;

          const matched = offersByLot.get(lotName) ?? [];

          matched.push({
            ...offerLot,
            offer_no: offer.name,
            offer_date: offer.offer_date,
            broker_type: offer.broker_type,
            offer_status: offer.workflow_state,
          });

          offersByLot.set(lotName, matched);
        }
      }

      // SaleBook grouped by Lot.
      // Records are ordered newest first, so the first record per Lot wins.
      const saleBookByLot = new Map<string, Record<string, unknown>>();

      for (const document of saleBookDocuments) {
        const sale = serialise(document);
        const lotName = String(sale.lot ?? "");

        if (!lotName || saleBookByLot.has(lotName)) continue;

        saleBookByLot.set(lotName, sale);
      }

      // Latest completed TeaTesting record grouped by Lot.
      const teaTestingByLot = new Map<string, Record<string, unknown>>();

      for (const document of teaTestingDocuments) {
        const testing = serialise(document);

        if (Number(testing.docstatus) !== 51) continue;

        const lotName = String(testing.lot ?? "");

        if (!lotName || teaTestingByLot.has(lotName)) continue;

        teaTestingByLot.set(lotName, testing);
      }

      const records = lotDocuments.flatMap((document) => {
        const lot = serialise(document);
        const lotName = String(lot.name);

        const bags = Number(lot.bags ?? 0);
        const netKgPerBag = Number(lot.net_kg_per_bag ?? 0);

        const matchedOffers = offersByLot.get(lotName) ?? [];

        if (matchedOffers.length === 0) {
          return [];
        }

        const sale = saleBookByLot.get(lotName);
        const testing = teaTestingByLot.get(lotName);

        return matchedOffers.map((offer) => ({
          ...lot,

          // OfferSheet fields
          offer_no: String(offer.offer_no ?? ""),
          offer_date: offer.offer_date ?? null,
          broker_type: String(offer.broker_type ?? ""),
          asking_rate: Number(offer.asking_rate ?? 0),
          remarks: offer.remarks ?? null,

          // Use OfferSheet workflow state for report filtering
          workflow_state: offer.offer_status ?? null,

          // Lots fields
          arrival_date: lot.arrival_date ?? null,

          // SaleBook fields
          sale_type: sale?.sale_type ?? null,
          tf: sale?.tf ?? null,

          // TeaTesting fields
          tested_grade: testing?.tested_grade ?? null,
          sample_date: testing?.sample_date ?? null,
          appearance: testing?.appearance ?? null,
          infusion: testing?.infusion ?? null,
          liquor: testing?.liquor ?? null,
          taste: testing?.taste ?? null,
          defects: testing?.defects ?? null,
          test_remarks: testing?.test_remarks ?? null,

          bags,
          net_kg_per_bag: netKgPerBag,
          total_kgs: bags * netKgPerBag,
        }));
      });

      return {
        documents: records,
        total_count: totalCount,
        limit,
        offset,
      };
    },
    {
      requireAuth: true,
    },
  );

  /**
   * Get previous confirmed offers for a Lot.
   */
  registry.register(
    "offers.get_previous_by_lot",
    async (ctx) => {
      const app = await getNodra();

      const lotName = String(ctx.args.lot ?? "").trim();

      if (!lotName) {
        throw new Error("Lot is required.");
      }

      const offerSheets = await app.orm.getList("OfferSheet", {
        limit: 1000,
        offset: 0,
        orderBy: "offer_date desc",
        filters: {
          docstatus: 51,
        },
      });

      const documents: RecordData[] = [];

      for (const document of offerSheets) {
        const offer = serialise(document);

        const offerLots = Array.isArray(offer.offer_lots)
          ? offer.offer_lots
          : [];

        for (const item of offerLots) {
          if (!isRecord(item)) continue;

          if (String(item.lot ?? "").trim() !== lotName) {
            continue;
          }

          documents.push({
            offer_name: String(offer.name ?? ""),
            offer_date: offer.offer_date ?? null,
            broker_type: offer.broker_type ?? "",
            asking_rate: toNumber(item.asking_rate),
            remarks: item.remarks ?? "",
          });
        }
      }

      documents.sort((a, b) => {
        const dateDifference =
          toDateValue(b.offer_date) - toDateValue(a.offer_date);

        if (dateDifference !== 0) {
          return dateDifference;
        }

        return String(b.offer_name ?? "").localeCompare(
          String(a.offer_name ?? ""),
        );
      });

      return {
        documents,
        total_count: documents.length,
      };
    },
    {
      requireAuth: true,
    },
  );

  /**
   * Avaiable lots
   */

  registry.register(
    "offers.available_lots",
    async () => {
      const app = await getNodra();
      const stockService = new StockService(app.orm);

      const lotDocuments = await app.orm.getAll("Lots", {
        limit: 1000,
        offset: 0,
        filters: {
          docstatus: 51,
        },
        withRelations: {
          test_report: {
            doctype: "TeaTesting",
            linkField: "lot",
            type: "one",
            orderBy: "sample_date desc",
            filters: {
              docstatus: 51,
            },
            fields: ["appearance", "infusion", "liquor", "sample_date"],
          },
        },
      });

      // Check actual stock balance for each confirmed Lot.
      const availableLots = await Promise.all(
        lotDocuments.map(async (document) => {
          const lot = document as RecordData & {
            test_report?: RecordData | null;
          };

          const lotName = String(lot.name ?? "").trim();

          if (!lotName) return null;

          const stock = await stockService.getLotStockBalance(lotName);

          // Lot must have remaining Factory stock.
          if (stock.factory_bags <= 0 || stock.factory_quantity <= 0) {
            return null;
          }

          // Lot must not have stock transferred to Warehouse.
          if (stock.warehouse_bags > 0 || stock.warehouse_quantity > 0) {
            return null;
          }

          const testing = lot.test_report;

          const bags = toNumber(lot.bags);
          const netKgPerBag = toNumber(lot.net_kg_per_bag);

          // Remove relation property from the parent Lot data.
          const { test_report: _testReport, ...lotData } = lot;

          return {
            ...lotData,

            // TeaTesting information
            test: [testing?.appearance, testing?.infusion, testing?.liquor]
              .map((value) => String(value ?? "").trim())
              .filter(Boolean)
              .join(" / "),

            liquor: testing?.liquor ?? "",

            // Current stock information
            factory_stock: stock.factory_bags,
            factory_quantity: stock.factory_quantity,

            // Lot quantities
            bags,
            net_kg_per_bag: netKgPerBag,
            total_kg: bags * netKgPerBag,
          };
        }),
      );

      const documents = availableLots.filter(
        (lot): lot is NonNullable<typeof lot> => lot !== null,
      );

      console.log(documents);

      return {
        documents,
        total_count: documents.length,
      };
    },
    {
      requireAuth: true,
    },
  );
}
